const state={...initial,route:'studio',tab:'design',wallet:null,midnight:null,simulation:null,seqPreset:'distribution',seqMode:'preset',seqCustom:null,seqResult:null,supply:{action:'mint',actor:'issuer',amount:'1000'},supplyResult:null,supplySeqPreset:'schedule',supplySeqMode:'preset',supplySeqCustom:null,supplySeqResult:null,timelinePreset:'lifecycle',timelineMode:'preset',timelineCustom:null,timelineResult:null,subPreset:null,subResult:null,seizurePreset:'lawful',seizureResult:null,scenario:{amount:'250',recipient:'approved'},tip:null,tipError:'',reference:null,referenceError:'',asset:null,assetQueried:false,assetLoading:false,assetError:'',saving:true,requestId:0,registry:null,registryError:'',deployment:null,deploymentError:'',deploymentLoading:false,credit:{principal:50000,rate:8,months:12,collateral:80000,advance:70},extraPayment:0,payoffTarget:'',refinance:{paymentsMade:0,newRate:4,newMonths:12,closingCosts:500},stress:{dropPercent:25},rateStress:{shockPoints:3,paymentBudget:4500},dscr:{monthlyIncome:6000,requiredDscr:1.25},balloon:{balloonMonths:6},apr:{upfrontFees:500},interestOnly:{interestOnlyMonths:6},lumpSum:{lumpMonth:6,lumpAmount:10000},eligibility:{score:78,minimum:65,age:28,adult:true,region:true,approved:true},eligibilityResult:null,cohortResult:null};

function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4300);}
function save(){try{const errors=validateDesign(state.design);if(!errors.length)localStorage.setItem('prism-design-v1',JSON.stringify(makeManifest(state.design,state.network)));state.saving=true;}catch{state.saving=false;}updateSave();}
function updateSave(){const el=$('#save-status');if(el)el.textContent=validateDesign(state.design).length?'Unsaved changes · check fields':state.saving?'Draft saved on this device':'Storage unavailable · export to save';}
function shell(){
  $('#app').innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand" href="#studio" aria-label="PRISM home"><img src="./favicon.svg" alt="" width="38" height="38"><span>PRISM<small>CARDANO STUDIO</small></span></a><div class="sidebar-label">WORKSPACE <span>v1.31</span></div><nav aria-label="Main navigation">${navItems.map(([id,ic,label])=>`<a href="#${id}" data-nav="${id}">${icon(ic)}<span>${label}</span>${id==='midnight'?'<span class="nav-mark">NEW</span>':''}</a>`).join('')}</nav><div class="sidebar-notice">${icon('layers')}<span>Built around CIP-113<small>Standard status: Proposed</small></span></div><div class="sidebar-bottom"><div class="open-source"><span class="mini-label">MADE FOR CARDANO</span><h3>Build something<br>that matters.</h3><p>Open source. Community first.</p>${external(CONFIG.github,`${icon('github')} Explore the code`,'btn secondary compact')}</div><button class="support-link" data-action="donate">${icon('heart')} Support this project</button><a class="creator" href="https://x.com/${CONFIG.x}" target="_blank" rel="noopener noreferrer"><span class="avatar">K</span><span>Built by KShot<small>@${CONFIG.x}</small></span>${icon('x')}</a></div></aside><div class="mobile-shade" data-action="menu"></div><div class="app-body"><header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><span class="desktop-only">Workspace</span><span class="slash desktop-only">/</span><strong id="breadcrumb">Token studio</strong></div><div class="topbar-actions"><label class="network-select">${icon('globe')}<span class="sr-only">Cardano network</span><select id="network-select" aria-label="Cardano network">${Object.entries(NETWORKS).map(([key,n])=>`<option value="${key}" ${key===state.network?'selected':''}>${n.name}${key!=='mainnet'?' testnet':''}</option>`).join('')}</select></label><button class="btn primary wallet-button" data-action="wallet" id="wallet-button">${icon('wallet')}<span>Connect wallet</span></button></div></header><main id="main" tabindex="-1"></main><footer class="footer"><span>PRISM is an independent, open-source project by <a href="https://x.com/${CONFIG.x}" target="_blank" rel="noopener noreferrer">@${CONFIG.x}</a>.</span><span>Cardano × RealFi × Midnight <span class="footer-separator">/</span> <button data-action="share">Share the project ${icon('share')}</button></span></footer></div><input id="import-file" type="file" accept="application/json,.json" hidden>`;
}
function header(eyebrow,title,description,action=''){return `<section class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</section>`;}
function render(){
  const route=location.hash.slice(1)||'studio';state.route=navItems.some(n=>n[0]===route)?route:'studio';
  $$('[data-nav]').forEach(el=>{const active=el.dataset.nav===state.route;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  $('#breadcrumb').textContent=navItems.find(n=>n[0]===state.route)[2];
  document.title=`PRISM · ${navItems.find(n=>n[0]===state.route)[2]}`;
  document.body.classList.remove('menu-open');$('.mobile-menu').setAttribute('aria-expanded','false');updateNavAccess();
  const pages={studio:studio,learn:learn,realfi:realfi,midnight:midnight,network:network,guide:guide};
  $('#main').innerHTML=pages[state.route]();
  if(state.route==='studio'){renderPreview();updateSave();}
  if(state.route==='realfi')updateCredit();
  if(state.route==='network')renderNetworkData();
}

function studio(){return `${header('THE PROGRAMMABLE TOKEN STUDIO','Your asset. <span class="accent-text">Your rules.</span>','Turn a token idea into a testable design. Built around Cardano’s CIP-113.',`<button class="btn secondary" data-action="import">${icon('upload')} Import design</button>`)}<div class="ecosystem-strip"><span>${icon('layers')} Native Cardano assets</span><span class="strip-divider"></span><a href="#realfi">${icon('chart')} Real-world possibilities</a><span class="strip-divider"></span><a href="#midnight">${icon('moon')} Privacy with Midnight</a><span class="strip-end">DESIGN WORKSPACE ${icon('sliders')}</span></div><div class="section-heading"><h2>Start with a possibility</h2><span>Choose a template to shape your rules</span></div><div class="template-grid">${TEMPLATES.map(t=>`<button class="template ${state.design.template===t.id?'selected':''}" data-template="${t.id}" aria-pressed="${state.design.template===t.id}"><span class="template-icon ${t.accent}">${icon(t.icon)}</span><span><strong>${t.name}</strong><small>${t.description}</small></span><span class="selection-dot">${state.design.template===t.id?icon('check'):''}</span></button>`).join('')}</div><div class="studio-layout"><section class="panel editor-panel"><div class="editor-tabs" role="tablist" aria-label="Studio steps">${[['design','01','Design'],['test','02','Test transfer'],['export','03','Export']].map(([key,num,label])=>`<button role="tab" id="tab-${key}" aria-controls="editor-content" aria-selected="${state.tab===key}" tabindex="${state.tab===key?0:-1}" data-tab="${key}" class="${state.tab===key?'active':''}"><span>${num}</span>${label}</button>`).join('')}</div><div id="editor-content" role="tabpanel" aria-labelledby="tab-${state.tab}">${editorContent()}</div><div class="editor-footer"><span>${icon('lock')}<span id="save-status">Draft saved on this device</span></span><button class="text-button" data-action="reset">Reset design</button></div></section><aside class="preview-column" aria-label="Design preview"><div id="design-preview"></div><section class="panel architecture"><div class="section-heading"><h2>How the rules connect</h2>${pill('CIP-113')}</div><div class="architecture-row"><div>${icon('wallet')}<span>Smart wallet</span></div><span class="connector"></span><div>${icon('layers')}<span>Dispatcher</span></div><span class="connector"></span><div>${icon('shield')}<span>Rule delegate</span></div></div><p>A transfer invokes the shared framework and token-specific logic. Your issuer defines the rules.</p><a href="#guide" class="text-link">Explore the architecture ${icon('book')}</a></section><div class="quiet-note">${icon('info')}<span>This is a design workspace. It does not issue tokens or submit transactions.</span></div></aside></div>`;}
function editorContent(){
  const d=state.design;
  if(state.tab==='test')return `<div class="editor-body"><div class="panel-title"><div><h2>Put your rules to the test</h2><p>Try a transfer between fictional participants.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="form-grid">${field('Transfer amount',`<div class="input-suffix"><input id="test-amount" inputmode="decimal" value="${esc(state.scenario.amount)}" autocomplete="off"><span>${esc(d.ticker)}</span></div>`)}${field('Test recipient',`<select id="test-recipient">${Object.entries(PARTICIPANTS).map(([k,v])=>`<option value="${k}" ${state.scenario.recipient===k?'selected':''}>${v.name}</option>`).join('')}</select>`)}</div>${d.pausable?`<label class="check-label pause-control"><input type="checkbox" id="test-paused" ${d.paused?'checked':''}> Simulate an issuer pause</label>`:''}<button class="btn primary full" data-action="simulate">${icon('play')} Run transfer simulation</button><div id="simulation-result" aria-live="polite">${simulationResult()}</div><p class="fine-print">Checks model your settings. They do not execute a validator, check an on-chain balance, verify identity, or produce a transaction.</p>${sequenceLab()}${supplyLab()}${timelineLab()}${substandardLab()}</div>`;
  if(state.tab==='export')return `<div class="editor-body"><div class="panel-title"><div><h2>Take your idea further</h2><p>A portable design for you and your contributors.</p></div>${icon('code')}</div><div class="notice">${icon('info')}<span>This JSON is a PRISM design manifest. A developer must implement and review the token’s validators before deployment.</span></div><div class="code-header"><span>prism-design.json</span><button class="icon-btn" data-action="copy-manifest" aria-label="Copy design JSON">${icon('copy')}</button></div><pre class="code-preview" id="manifest-code">${esc(manifestText())}</pre><div class="button-row"><button class="btn primary" data-action="export">${icon('download')} Download design</button><a class="btn secondary" href="#guide">${icon('book')} Build guide</a></div><p class="fine-print">Imports are verified before they open: amounts must be exact decimal strings (a JSON number is rejected, never rounded), the token summary must match the design, and a file claiming deployment, a verified proof, or an affiliation is rejected.</p><div class="section-divider"></div><div class="panel-title"><div><h2>Registry entry preview</h2><p>The design information a CIP-113 registry entry would need to describe — shown before any code exists.</p></div>${pill('NOT A CIP DATUM','amber')}</div><div class="notice">${icon('info')}<span><strong>Application-specific preview, not a CIP datum.</strong> A real registry entry is an on-chain linked-list node created by the pinned reference implementation, carrying a deployed token policy ID and a Plutus Data encoding. This preview has neither — it lists what your design contributes and what a deployment still has to supply. PRISM does not register anything.</span></div><div class="code-header"><span>prism-registry-preview.json</span><button class="icon-btn" data-action="copy-registry-preview" aria-label="Copy registry preview JSON">${icon('copy')}</button></div><pre class="code-preview" id="registry-preview-code">${esc(registryPreviewText())}</pre><div class="button-row"><button class="btn secondary" data-action="export-registry-preview">${icon('download')} Download preview</button></div><p class="fine-print">Amounts are exact base units (BigInt). The preview is deterministic — exporting the same design twice gives the same file, so reviewers can diff it.</p></div>`;
  return `<div class="editor-body"><div class="panel-title"><div><h2>Token identity</h2><p>Every asset starts with a name.</p></div><span class="step-label">01 / 03</span></div><div class="form-grid"><div class="span-two">${field('Asset name',`<input data-design="tokenName" value="${esc(d.tokenName)}" maxlength="64" autocomplete="off" placeholder="Give your asset a name">`,'Maximum 32 UTF-8 bytes.')}</div>${field('Ticker',`<input data-design="ticker" value="${esc(d.ticker)}" maxlength="8" autocomplete="off" spellcheck="false">`)}${field('Decimals',`<select data-design="decimals">${[0,1,2,3,4,5,6].map(n=>`<option ${d.decimals===n?'selected':''} value="${n}">${n}${n===0?' · whole tokens':''}</option>`).join('')}</select>`)}${field('Designed supply',`<input data-design="supply" value="${esc(d.supply)}" inputmode="decimal" autocomplete="off">`)}${field('Transfer limit',`<div class="input-suffix"><input data-design="limit" value="${esc(d.limit)}" inputmode="decimal" autocomplete="off"><span id="limit-ticker">${esc(d.ticker)}</span></div>`)}</div><div id="design-errors" class="validation" role="status"></div><div class="section-divider"></div><div class="panel-title rules-title"><div><h2>Make the rules</h2><p>Choose what a transfer needs to satisfy.</p></div><span id="rule-count" class="count-badge">4 active</span></div><div class="rule-list">${toggle('allowlist','Approved participants','Only modeled allowlist members can receive.','users')}${toggle('limitEnabled','Transfer limits','Set the maximum amount per transfer.','sliders')}${toggle('pausable','Issuer controls','Model transfer pauses and frozen participants.','shield')}${toggle('identity','Private eligibility','Plan eligibility checks with a Midnight attestation.','fingerprint')}</div><div class="section-divider"></div><div class="panel-title rules-title"><div><h2>CIP-113 substandard module</h2><p>The reference rule set a transfer hook would implement.</p></div>${pill('LOCAL MODEL','amber')}</div>${field('Reference module',`<select data-design="substandard" aria-label="CIP-113 substandard module">${SUBSTANDARDS.map(s=>`<option value="${s.id}" ${d.substandard===s.id?'selected':''}>${s.name}</option>`).join('')}</select>`)}<div id="substandard-summary">${substandardSummary()}</div><div class="section-divider"></div><div class="panel-title rules-title"><div><h2>Design review</h2><p>What this design's own settings imply \u2014 before you test or export it.</p></div>${pill('LOCAL REVIEW','amber')}</div><div id="design-review">${designReview()}</div><button class="btn primary full next-step" data-tab="test">${icon('play')} Test this design</button></div>`;
}
function manifestText(){try{return JSON.stringify(makeManifest(state.design,state.network),null,2);}catch(e){return `Fix the design before exporting:\n${e.message}`;}}
function registryPreviewText(){try{return JSON.stringify(registryDatumPreview(state.design,state.network),null,2);}catch(e){return `Fix the design before previewing:\n${e.message}`;}}
function renderPreview(){
  if(!$('#design-preview'))return;
  const d=state.design,t=TEMPLATES.find(t=>t.id===d.template),count=['allowlist','limitEnabled','pausable','identity'].filter(k=>d[k]).length;
  $('#design-preview').innerHTML=`<div class="preview-heading"><span>YOUR ASSET, AT A GLANCE</span>${pill('DESIGN · NOT ISSUED')}</div><div class="asset-card ${t.accent}"><div class="asset-card-top"><span class="asset-symbol">${icon(t.icon)}</span><span class="asset-standard">CARDANO<br><b>CIP–113</b></span></div><div class="asset-card-title"><span class="asset-ticker">${esc(d.ticker)||'TOKEN'}</span><h2>${esc(d.tokenName)||'Your new asset'}</h2><span>Programmable token design</span></div><div class="asset-card-bottom"><div><span>DESIGNED SUPPLY</span><strong>${Number.isFinite(Number(d.supply))?fmt(Number(d.supply)):'—'}</strong></div><div><span>NETWORK</span><strong>${NETWORKS[state.network].name}</strong></div></div></div><div class="panel preview-details"><div><span>Asset type</span><strong>${t.name}</strong></div><div><span>Precision</span><strong>${d.decimals} decimals</strong></div><div><span>Transfer policy</span><strong>${d.allowlist?'Permissioned':'Open access'}</strong></div><div><span>Substandard</span><strong>${esc(substandardById(d.substandard)?.short??'Generic rules')}</strong></div><div><span>Active rules</span><strong class="accent-text">${count} configured</strong></div><div><span>Privacy plan</span><strong>${d.identity?`${icon('moon')} Midnight`:'None selected'}</strong></div></div>`;
  const errors=validateDesign(d);if($('#design-errors'))$('#design-errors').textContent=errors.join(' ');
  if($('#substandard-summary'))$('#substandard-summary').innerHTML=substandardSummary();
  if($('#design-review'))$('#design-review').innerHTML=designReview();
  if($('#rule-count'))$('#rule-count').textContent=`${count} active`;
  if($('#limit-ticker'))$('#limit-ticker').textContent=d.ticker;
  updateSave();
}
function simulationResult(){
  const r=state.simulation;
  if(!r)return `<div class="simulation-empty">${icon('play')}<strong>What happens when this token moves?</strong><span>Run a scenario to see each rule evaluated.</span></div>`;
  return `<div class="simulation-result ${r.allowed?'passed':'failed'}"><div class="result-heading"><span class="result-icon">${icon(r.allowed?'check':'close')}</span><div><h3>${r.allowed?'Transfer allowed by model':'Transfer blocked by model'}</h3><p>${r.checks.filter(c=>c.pass).length} of ${r.checks.length} checks passed · no transaction sent</p></div></div><div class="check-results">${r.checks.map(c=>`<div class="check-result ${c.pass?'pass':'fail'}">${icon(c.pass?'check':'close')}<span><strong>${c.name}</strong><small>${esc(c.detail)}</small></span></div>`).join('')}</div></div>`;
}

function sequencePresets(d){
  const cap=d.limitEnabled?d.limit:'250';
  return [
    {id:'distribution',label:'Distribution & onward moves',steps:[{from:'issuer',to:'approved',amount:'250'},{from:'approved',to:'pending',amount:'100'},{from:'approved',to:'blocked',amount:'50'},{from:'issuer',to:'approved',amount:'100'}]},
    {id:'fund-spend',label:'Fund, spend back, overspend',steps:[{from:'issuer',to:'approved',amount:'200'},{from:'approved',to:'issuer',amount:'150'},{from:'approved',to:'issuer',amount:'100'}]},
    {id:'cap-pair',label:'Two transfers at the cap',steps:[{from:'issuer',to:'approved',amount:cap},{from:'issuer',to:'approved',amount:cap}]},
  ];
}
function currentSeqPreset(){const list=sequencePresets(state.design);return list.find(p=>p.id===state.seqPreset)??list[0];}
function customSteps(){if(!state.seqCustom)state.seqCustom=copySequenceSteps(currentSeqPreset().steps);return state.seqCustom;}
function seqSteps(){return state.seqMode==='custom'?customSteps():currentSeqPreset().steps;}
function sequenceLab(){
  const d=state.design,custom=state.seqMode==='custom',steps=seqSteps();
  const accountOptions=sel=>Object.entries(LEDGER_ACCOUNTS).map(([k,v])=>`<option value="${k}" ${k===sel?'selected':''}>${v.name}</option>`).join('');
  const list=custom
    ?`<div class="seq-editor">${steps.map((s,i)=>`<div class="seq-edit-row"><span class="seq-num">${i+1}</span><label class="sr-only" for="seq-from-${i}">Step ${i+1} sender</label><select id="seq-from-${i}" class="seq-from" data-seq-field="from" data-seq-index="${i}">${accountOptions(s.from)}</select><span class="seq-arrow" aria-hidden="true">→</span><label class="sr-only" for="seq-to-${i}">Step ${i+1} recipient</label><select id="seq-to-${i}" class="seq-to" data-seq-field="to" data-seq-index="${i}">${accountOptions(s.to)}</select><label class="sr-only" for="seq-amount-${i}">Step ${i+1} amount in ${esc(d.ticker)}</label><span class="seq-amount"><input id="seq-amount-${i}" data-seq-field="amount" data-seq-index="${i}" inputmode="decimal" autocomplete="off" value="${esc(s.amount)}"><span>${esc(d.ticker)}</span></span><span class="seq-row-actions"><button class="icon-btn" data-seq-move="-1" data-seq-index="${i}" ${i===0?'disabled':''} aria-label="Move step ${i+1} up">${icon('chevron','seq-up')}</button><button class="icon-btn" data-seq-move="1" data-seq-index="${i}" ${i===steps.length-1?'disabled':''} aria-label="Move step ${i+1} down">${icon('chevron','seq-down')}</button><button class="icon-btn" data-seq-remove="${i}" ${steps.length<=1?'disabled':''} aria-label="Remove step ${i+1}">${icon('close')}</button></span></div>`).join('')}</div><button class="btn secondary full seq-add" data-action="seq-add" ${steps.length>=12?'disabled':''}>${icon('plus')} Add a transfer step</button>`
    :`<ol class="seq-steps">${steps.map((s,i)=>`<li><span class="seq-num">${i+1}</span><span>${esc(LEDGER_ACCOUNTS[s.from]?.name??s.from)} → ${esc(LEDGER_ACCOUNTS[s.to]?.name??s.to)}</span><strong>${esc(s.amount)} ${esc(d.ticker)}</strong></li>`).join('')}</ol>`;
  return `<div class="section-divider"></div><div class="panel-title"><div><h2>Sequence lab · transfers in order</h2><p>One transfer changes the balances the next one is checked against. The issuer starts holding the full designed supply; every other modeled account starts at zero.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="preset-chips" role="group" aria-label="Transfer sequence scenarios">${sequencePresets(d).map(p=>`<button class="chip ${!custom&&state.seqPreset===p.id?'selected':''}" data-seq-preset="${p.id}" aria-pressed="${!custom&&state.seqPreset===p.id}">${p.label}</button>`).join('')}<button class="chip ${custom?'selected':''}" data-action="seq-customize" aria-pressed="${custom}">${custom?'Your own sequence':'Build your own'}</button></div>${custom?`<p class="fine-print seq-custom-note">Start from the preset you were viewing, then change senders, recipients, and amounts, add steps (up to 12), reorder them, or remove them. Editing clears the last run — run it again to see the new order evaluated.</p>`:''}${list}<button class="btn primary full" data-action="seq-simulate">${icon('play')} Run sequence</button><div id="seq-result" aria-live="polite">${seqResultView()}</div><p class="fine-print">A modeled ledger only: balances are fictional, no wallet or on-chain balance is read, and a blocked step leaves every balance unchanged — later steps are still evaluated against the ledger as it stands, so you can see the knock-on effect of a denial.</p>`;
}
function seqResultView(){
  const r=state.seqResult,d=state.design;
  if(!r)return `<div class="simulation-empty">${icon('layers')}<strong>What happens across several transfers?</strong><span>Run a sequence to watch balances and rules interact, step by step.</span></div>`;
  if(r.invalid)return `<div class="validation" role="alert">Fix the design before running a sequence: ${esc((r.errors??[]).join(' '))}</div>`;
  return `<div class="simulation-result ${r.appliedCount===r.steps.length?'passed':'failed'}"><div class="result-heading"><span class="result-icon">${icon(r.appliedCount===r.steps.length?'check':'close')}</span><div><h3>${r.appliedCount} of ${r.steps.length} transfers applied in the model</h3><p>${esc(formatUnits(BigInt(r.transferredBaseUnits),d.decimals))} ${esc(d.ticker)} moved in total · no transaction sent</p></div></div><div class="seq-balances"><h4>FINAL MODELED BALANCES</h4><dl>${Object.entries(r.balances).map(([k,v])=>`<div><dt>${esc(LEDGER_ACCOUNTS[k]?.name??k)}</dt><dd>${esc(formatUnits(BigInt(v),d.decimals))} ${esc(d.ticker)}</dd></div>`).join('')}</dl></div>${r.steps.map((s,i)=>`<div class="seq-step ${s.allowed?'pass':'fail'}"><div class="seq-step-head">${icon(s.allowed?'check':'close')}<strong>Step ${i+1} · ${esc(LEDGER_ACCOUNTS[s.from]?.name??s.from)} → ${esc(LEDGER_ACCOUNTS[s.to]?.name??s.to)} · ${esc(s.amount)} ${esc(d.ticker)}</strong><span>${s.allowed?'Applied':'Blocked · balances unchanged'}</span></div><div class="check-results">${s.checks.map(c=>`<div class="check-result ${c.pass?'pass':'fail'}">${icon(c.pass?'check':'close')}<span><strong>${c.name}</strong><small>${esc(c.detail)}</small></span></div>`).join('')}</div></div>`).join('')}</div>`;
}

function supplyLab(){
  const d=state.design,s=state.supply;
  return `<div class="section-divider"></div><div class="panel-title"><div><h2>Supply lab · mint &amp; burn</h2><p>The designed supply is an initial supply. Model the issuer minting more of it, or burning some of it, and see exactly where the supply would land.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="form-grid">${field('Supply change',`<select id="supply-action"><option value="mint" ${s.action==='mint'?'selected':''}>Mint new tokens</option><option value="burn" ${s.action==='burn'?'selected':''}>Burn existing tokens</option></select>`)}${field('Attempted by',`<select id="supply-actor"><option value="issuer" ${s.actor==='issuer'?'selected':''}>Issuer (issuance authority)</option><option value="other" ${s.actor==='other'?'selected':''}>Someone else</option></select>`)}<div class="span-two">${field('Amount',`<div class="input-suffix"><input id="supply-amount" inputmode="decimal" value="${esc(s.amount)}" autocomplete="off"><span>${esc(d.ticker)}</span></div>`)}</div></div><button class="btn primary full" data-action="supply-simulate">${icon('play')} Run supply change</button><div id="supply-result" aria-live="polite">${supplyResultView()}</div><p class="fine-print">PRISM's generic issuance model — not a Foundation substandard module, and a real token's issuance logic defines its own authority and bounds. Transfer rules (allowlist, per-transfer cap, pause) gate transfers, not issuance, so they are not applied here. No tokens are minted or burned; nothing is signed or submitted.</p>${supplySequenceLab()}`;
}
function supplyResultView(){
  const r=state.supplyResult,d=state.design;
  if(!r)return `<div class="simulation-empty">${icon('coins')}<strong>What if the supply itself changes?</strong><span>Run a mint or burn to see the modeled supply move — exactly, in base units.</span></div>`;
  if(r.invalid)return `<div class="validation" role="alert">${esc(r.checks?.[0]?.detail??'Fix the design and amount before modeling a supply change.')}</div>`;
  const verb=r.action==='mint'?'Mint':'Burn';
  const resulting=r.allowed?`${esc(formatUnits(BigInt(r.supplyAfterBaseUnits),d.decimals))} ${esc(d.ticker)} · ${esc(r.supplyAfterBaseUnits)} base units`:`Unchanged — ${esc(formatUnits(BigInt(r.supplyBeforeBaseUnits),d.decimals))} ${esc(d.ticker)} (the change was blocked)`;
  return `<div class="simulation-result ${r.allowed?'passed':'failed'}"><div class="result-heading"><span class="result-icon">${icon(r.allowed?'check':'close')}</span><div><h3>${r.allowed?`${verb} applied in the model`:`${verb} blocked by the model`}</h3><p>${r.checks.filter(c=>c.pass).length} of ${r.checks.length} checks passed · no transaction sent</p></div></div><div class="seq-balances"><h4>MODELED SUPPLY</h4><dl><div><dt>Designed (initial) supply</dt><dd>${esc(formatUnits(BigInt(r.supplyBeforeBaseUnits),d.decimals))} ${esc(d.ticker)}</dd></div><div><dt>${verb} amount</dt><dd>${esc(formatUnits(BigInt(r.amountBaseUnits),d.decimals))} ${esc(d.ticker)}</dd></div><div><dt>Resulting supply</dt><dd>${resulting}</dd></div></dl></div><div class="check-results">${r.checks.map(c=>`<div class="check-result ${c.pass?'pass':'fail'}">${icon(c.pass?'check':'close')}<span><strong>${c.name}</strong><small>${esc(c.detail)}</small></span></div>`).join('')}</div></div>`;
}


function supplySeqPresets(){
  return [
    {id:'schedule',label:'Issuance schedule',steps:[{action:'mint',actor:'issuer',amount:'250000'},{action:'burn',actor:'issuer',amount:'100000'},{action:'mint',actor:'issuer',amount:'50000'}]},
    {id:'burn-remint',label:'Burn, then re-mint',steps:[{action:'burn',actor:'issuer',amount:'400000'},{action:'mint',actor:'issuer',amount:'400000'}]},
    {id:'authority',label:'Authority attempts',steps:[{action:'mint',actor:'other',amount:'10000'},{action:'mint',actor:'issuer',amount:'10000'},{action:'burn',actor:'other',amount:'5000'},{action:'burn',actor:'issuer',amount:'5000'}]},
  ];
}
function currentSupplySeqPreset(){const list=supplySeqPresets();return list.find(p=>p.id===state.supplySeqPreset)??list[0];}
function supplyCustomSteps(){if(!state.supplySeqCustom)state.supplySeqCustom=copySupplySteps(currentSupplySeqPreset().steps);return state.supplySeqCustom;}
function supplySeqSteps(){return state.supplySeqMode==='custom'?supplyCustomSteps():currentSupplySeqPreset().steps;}
function supplySequenceLab(){
  const d=state.design,custom=state.supplySeqMode==='custom',steps=supplySeqSteps();
  const list=custom
    ?`<div class="seq-editor">${steps.map((c,i)=>`<div class="seq-edit-row supply-seq-row"><span class="seq-num">${i+1}</span><label class="sr-only" for="supply-seq-action-${i}">Step ${i+1} supply change</label><select id="supply-seq-action-${i}" class="supply-seq-action" data-supply-seq-field="action" data-supply-seq-index="${i}"><option value="mint" ${c.action==='mint'?'selected':''}>Mint new tokens</option><option value="burn" ${c.action==='burn'?'selected':''}>Burn existing tokens</option></select><label class="sr-only" for="supply-seq-actor-${i}">Step ${i+1} attempted by</label><select id="supply-seq-actor-${i}" class="supply-seq-actor" data-supply-seq-field="actor" data-supply-seq-index="${i}"><option value="issuer" ${c.actor==='issuer'?'selected':''}>Issuer (issuance authority)</option><option value="other" ${c.actor==='other'?'selected':''}>Someone else</option></select><label class="sr-only" for="supply-seq-amount-${i}">Step ${i+1} amount in ${esc(d.ticker)}</label><span class="seq-amount"><input id="supply-seq-amount-${i}" data-supply-seq-field="amount" data-supply-seq-index="${i}" inputmode="decimal" autocomplete="off" value="${esc(c.amount)}"><span>${esc(d.ticker)}</span></span><span class="seq-row-actions"><button class="icon-btn" data-supply-seq-move="-1" data-supply-seq-index="${i}" ${i===0?'disabled':''} aria-label="Move step ${i+1} up">${icon('chevron','seq-up')}</button><button class="icon-btn" data-supply-seq-move="1" data-supply-seq-index="${i}" ${i===steps.length-1?'disabled':''} aria-label="Move step ${i+1} down">${icon('chevron','seq-down')}</button><button class="icon-btn" data-supply-seq-remove="${i}" ${steps.length<=1?'disabled':''} aria-label="Remove step ${i+1}">${icon('close')}</button></span></div>`).join('')}</div><button class="btn secondary full seq-add" data-action="supply-seq-add" ${steps.length>=12?'disabled':''}>${icon('plus')} Add a supply change</button>`
    :`<ol class="supply-seq-steps">${steps.map((c,i)=>`<li><span class="seq-num">${i+1}</span><span>${c.action==='mint'?'Mint':'Burn'} · attempted by ${c.actor==='issuer'?'issuer':'someone else'}</span><strong>${esc(c.amount)} ${esc(d.ticker)}</strong></li>`).join('')}</ol>`;
  return `<div class="section-divider"></div><div class="panel-title"><div><h2>Supply sequence · changes in order</h2><p>One supply change alters the supply the next one is checked against — a burn creates headroom a later mint can use, and a blocked change leaves the supply intact for the steps after it.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="preset-chips" role="group" aria-label="Supply sequence scenarios">${supplySeqPresets().map(p=>`<button class="chip ${!custom&&state.supplySeqPreset===p.id?'selected':''}" data-supply-seq-preset="${p.id}" aria-pressed="${!custom&&state.supplySeqPreset===p.id}">${p.label}</button>`).join('')}<button class="chip ${custom?'selected':''}" data-action="supply-seq-customize" aria-pressed="${custom}">${custom?'Your own sequence':'Build your own'}</button></div>${custom?`<p class="fine-print seq-custom-note">Start from the preset you were viewing, then change actions, actors, and amounts, add steps (up to 12), reorder them, or remove them. Editing clears the last run — run it again to see the new order evaluated.</p>`:''}${list}<button class="btn primary full" data-action="supply-seq-simulate">${icon('play')} Run supply sequence</button><div id="supply-seq-result" aria-live="polite">${supplySeqResultView()}</div><p class="fine-print">A modeled supply only: no tokens are minted or burned, no on-chain supply is read, and a blocked step leaves the modeled supply unchanged — later steps are still evaluated against the supply as it stands.</p>`;
}
function supplySeqResultView(){
  const r=state.supplySeqResult,d=state.design;
  if(!r)return `<div class="simulation-empty">${icon('coins')}<strong>What happens across an issuance schedule?</strong><span>Run a sequence to watch the modeled supply move step by step.</span></div>`;
  if(r.invalid)return `<div class="validation" role="alert">Fix the design before running a supply sequence: ${esc((r.errors??[]).join(' '))}</div>`;
  const net=BigInt(r.netChangeBaseUnits);
  return `<div class="simulation-result ${r.appliedCount===r.steps.length?'passed':'failed'}"><div class="result-heading"><span class="result-icon">${icon(r.appliedCount===r.steps.length?'check':'close')}</span><div><h3>${r.appliedCount} of ${r.steps.length} supply changes applied in the model</h3><p>Net change ${net>0n?'+':''}${esc(formatUnits(net,d.decimals))} ${esc(d.ticker)} · no transaction sent</p></div></div><div class="seq-balances"><h4>MODELED SUPPLY</h4><dl><div><dt>Designed (initial) supply</dt><dd>${esc(formatUnits(BigInt(r.initialSupplyBaseUnits),d.decimals))} ${esc(d.ticker)}</dd></div><div><dt>Final modeled supply</dt><dd>${esc(formatUnits(BigInt(r.finalSupplyBaseUnits),d.decimals))} ${esc(d.ticker)} · ${esc(r.finalSupplyBaseUnits)} base units</dd></div></dl></div>${r.steps.map((c,i)=>`<div class="seq-step ${c.allowed?'pass':'fail'}"><div class="seq-step-head">${icon(c.allowed?'check':'close')}<strong>Step ${i+1} · ${c.action==='mint'?'Mint':'Burn'} ${esc(c.amount)} ${esc(d.ticker)} · by ${c.actor==='issuer'?'issuer':'someone else'}</strong><span>${c.allowed?`Supply ${esc(formatUnits(BigInt(c.supplyBeforeBaseUnits),d.decimals))} → ${esc(formatUnits(BigInt(c.supplyAfterBaseUnits),d.decimals))} ${esc(d.ticker)}`:'Blocked · supply unchanged'}</span></div><div class="check-results">${c.checks.map(x=>`<div class="check-result ${x.pass?'pass':'fail'}">${icon(x.pass?'check':'close')}<span><strong>${x.name}</strong><small>${esc(x.detail)}</small></span></div>`).join('')}</div></div>`).join('')}</div>`;
}

function timelinePresets(){
  return [
    {id:'lifecycle',label:'Mint, distribute, burn the rest',steps:[{kind:'supply',action:'mint',actor:'issuer',amount:'50000'},{kind:'transfer',from:'issuer',to:'approved',amount:'10000'},{kind:'transfer',from:'issuer',to:'approved',amount:'10000'},{kind:'supply',action:'burn',actor:'issuer',amount:'30000'}]},
    {id:'distributed-burn',label:'Burning what was already distributed',steps:[{kind:'transfer',from:'issuer',to:'approved',amount:'10000'},{kind:'supply',action:'burn',actor:'issuer',amount:'995000'},{kind:'supply',action:'burn',actor:'issuer',amount:'5000'}]},
    {id:'denial-chain',label:'Denials in the middle',steps:[{kind:'supply',action:'mint',actor:'other',amount:'10000'},{kind:'transfer',from:'issuer',to:'pending',amount:'100'},{kind:'transfer',from:'issuer',to:'approved',amount:'100'},{kind:'supply',action:'burn',actor:'other',amount:'50'}]},
  ];
}
function currentTimelinePreset(){const list=timelinePresets();return list.find(p=>p.id===state.timelinePreset)??list[0];}
function timelineCustomSteps(){if(!state.timelineCustom)state.timelineCustom=copyTimelineSteps(currentTimelinePreset().steps);return state.timelineCustom;}
function timelineSteps(){return state.timelineMode==='custom'?timelineCustomSteps():currentTimelinePreset().steps;}
function timelineLab(){
  const d=state.design,custom=state.timelineMode==='custom',steps=timelineSteps();
  const accountOptions=sel=>Object.entries(LEDGER_ACCOUNTS).map(([k,v])=>`<option value="${k}" ${k===sel?'selected':''}>${v.name}</option>`).join('');
  const list=custom
    ?`<div class="seq-editor">${steps.map((s,i)=>`<div class="seq-edit-row timeline-row"><span class="seq-num">${i+1}</span><label class="sr-only" for="timeline-kind-${i}">Step ${i+1} kind</label><select id="timeline-kind-${i}" class="timeline-kind" data-timeline-field="kind" data-timeline-index="${i}"><option value="transfer" ${s.kind==='transfer'?'selected':''}>Transfer</option><option value="supply" ${s.kind==='supply'?'selected':''}>Supply change</option></select>${s.kind==='transfer'?`<label class="sr-only" for="timeline-from-${i}">Step ${i+1} sender</label><select id="timeline-from-${i}" class="timeline-from" data-timeline-field="from" data-timeline-index="${i}">${accountOptions(s.from)}</select><span class="seq-arrow" aria-hidden="true">→</span><label class="sr-only" for="timeline-to-${i}">Step ${i+1} recipient</label><select id="timeline-to-${i}" class="timeline-to" data-timeline-field="to" data-timeline-index="${i}">${accountOptions(s.to)}</select>`:`<label class="sr-only" for="timeline-action-${i}">Step ${i+1} supply change</label><select id="timeline-action-${i}" class="timeline-action" data-timeline-field="action" data-timeline-index="${i}"><option value="mint" ${s.action==='mint'?'selected':''}>Mint new tokens</option><option value="burn" ${s.action==='burn'?'selected':''}>Burn existing tokens</option></select><label class="sr-only" for="timeline-actor-${i}">Step ${i+1} attempted by</label><select id="timeline-actor-${i}" class="timeline-actor" data-timeline-field="actor" data-timeline-index="${i}"><option value="issuer" ${s.actor==='issuer'?'selected':''}>Issuer (issuance authority)</option><option value="other" ${s.actor==='other'?'selected':''}>Someone else</option></select>`}<label class="sr-only" for="timeline-amount-${i}">Step ${i+1} amount in ${esc(d.ticker)}</label><span class="seq-amount"><input id="timeline-amount-${i}" data-timeline-field="amount" data-timeline-index="${i}" inputmode="decimal" autocomplete="off" value="${esc(s.amount)}"><span>${esc(d.ticker)}</span></span><span class="seq-row-actions"><button class="icon-btn" data-timeline-move="-1" data-timeline-index="${i}" ${i===0?'disabled':''} aria-label="Move step ${i+1} up">${icon('chevron','seq-up')}</button><button class="icon-btn" data-timeline-move="1" data-timeline-index="${i}" ${i===steps.length-1?'disabled':''} aria-label="Move step ${i+1} down">${icon('chevron','seq-down')}</button><button class="icon-btn" data-timeline-remove="${i}" ${steps.length<=1?'disabled':''} aria-label="Remove step ${i+1}">${icon('close')}</button></span></div>`).join('')}</div><div class="button-row seq-add"><button class="btn secondary" data-action="timeline-add-transfer" ${steps.length>=12?'disabled':''}>${icon('plus')} Add a transfer step</button><button class="btn secondary" data-action="timeline-add-supply" ${steps.length>=12?'disabled':''}>${icon('plus')} Add a supply step</button></div>`
    :`<ol class="timeline-steps">${steps.map((s,i)=>`<li><span class="seq-num">${i+1}</span><span>${s.kind==='supply'?(s.action==='mint'?'Mint':'Burn')+' · attempted by '+(s.actor==='issuer'?'issuer':'someone else'):esc(LEDGER_ACCOUNTS[s.from]?.name??s.from)+' → '+esc(LEDGER_ACCOUNTS[s.to]?.name??s.to)}</span><strong>${esc(s.amount)} ${esc(d.ticker)}</strong></li>`).join('')}</ol>`;
  return `<div class="section-divider"></div><div class="panel-title"><div><h2>Timeline lab · issuance &amp; transfers together</h2><p>Transfer steps and supply steps in one order, against one modeled state: a ledger of balances plus the supply those balances sum to. Minted tokens become transferable here, and tokens the issuer has distributed are no longer the issuer's to burn.</p></div>${pill('LOCAL SIMULATION','amber')}</div><div class="preset-chips" role="group" aria-label="Timeline scenarios">${timelinePresets().map(p=>`<button class="chip ${!custom&&state.timelinePreset===p.id?'selected':''}" data-timeline-preset="${p.id}" aria-pressed="${!custom&&state.timelinePreset===p.id}">${p.label}</button>`).join('')}<button class="chip ${custom?'selected':''}" data-action="timeline-customize" aria-pressed="${custom}">${custom?'Your own timeline':'Build your own'}</button></div>${custom?`<p class="fine-print seq-custom-note">Start from the preset you were viewing, then change step kinds, senders, recipients, actions, actors, and amounts, add steps (up to 12), reorder them, or remove them. Switching a step's kind converts it — its amount is kept and the new kind starts from its defaults. Editing clears the last run — run it again to see the new order evaluated.</p>`:''}${list}<button class="btn primary full" data-action="timeline-simulate">${icon('play')} Run timeline</button><div id="timeline-result" aria-live="polite">${timelineResultView()}</div><p class="fine-print">One modeled state only: the balances always sum to the modeled supply, minted tokens enter at the issuer, and a burn draws on the issuer's modeled holding — tokens held by other modeled accounts are not burned here. Transfer rules gate the transfer steps and issuance checks gate the supply steps; neither gates the other. No tokens are minted, burned, or moved, no wallet or on-chain state is read, and no transaction is produced.</p>`;
}
function timelineResultView(){
  const r=state.timelineResult,d=state.design;
  if(!r)return `<div class="simulation-empty">${icon('layers')}<strong>What happens when issuance and transfers interleave?</strong><span>Run a timeline to watch one running supply and one running ledger interact, step by step.</span></div>`;
  if(r.invalid)return `<div class="validation" role="alert">Fix the design before running a timeline: ${esc((r.errors??[]).join(' '))}</div>`;
  const net=BigInt(r.netChangeBaseUnits);
  return `<div class="simulation-result ${r.appliedCount===r.steps.length?'passed':'failed'}"><div class="result-heading"><span class="result-icon">${icon(r.appliedCount===r.steps.length?'check':'close')}</span><div><h3>${r.appliedCount} of ${r.steps.length} steps applied in the model</h3><p>${esc(formatUnits(BigInt(r.transferredBaseUnits),d.decimals))} ${esc(d.ticker)} transferred · supply net change ${net>0n?'+':''}${esc(formatUnits(net,d.decimals))} ${esc(d.ticker)} · no transaction sent</p></div></div><div class="seq-balances"><h4>FINAL MODELED STATE</h4><dl><div><dt>Final modeled supply</dt><dd>${esc(formatUnits(BigInt(r.finalSupplyBaseUnits),d.decimals))} ${esc(d.ticker)} · ${esc(r.finalSupplyBaseUnits)} base units</dd></div>${Object.entries(r.balances).map(([k,v])=>`<div><dt>${esc(LEDGER_ACCOUNTS[k]?.name??k)}</dt><dd>${esc(formatUnits(BigInt(v),d.decimals))} ${esc(d.ticker)}</dd></div>`).join('')}</dl></div>${r.steps.map((s,i)=>`<div class="seq-step ${s.allowed?'pass':'fail'}"><div class="seq-step-head">${icon(s.allowed?'check':'close')}<strong>Step ${i+1} · ${s.kind==='supply'?`${s.action==='mint'?'Mint':'Burn'} ${esc(s.amount)} ${esc(d.ticker)} · by ${s.actor==='issuer'?'issuer':'someone else'}`:`Transfer · ${esc(LEDGER_ACCOUNTS[s.from]?.name??s.from)} → ${esc(LEDGER_ACCOUNTS[s.to]?.name??s.to)} · ${esc(s.amount)} ${esc(d.ticker)}`}</strong><span>${s.allowed?(s.kind==='supply'?`Supply ${esc(formatUnits(BigInt(s.supplyBeforeBaseUnits),d.decimals))} → ${esc(formatUnits(BigInt(s.supplyAfterBaseUnits),d.decimals))} ${esc(d.ticker)}`:'Applied · supply unchanged'):'Blocked · state unchanged'}</span></div><div class="check-results">${s.checks.map(c=>`<div class="check-result ${c.pass?'pass':'fail'}">${icon(c.pass?'check':'close')}<span><strong>${c.name}</strong><small>${esc(c.detail)}</small></span></div>`).join('')}</div></div>`).join('')}</div>`;
}

const KYC_OK={certPresent:true,certTrustedIssuer:true,certSignatureValid:true,certNamesSender:true,certExpired:false,paused:false};
